    s=s.rstrip('.')
    m=re.match(r'^(?:In certain contexts |In no context )?(.*?) (is|is not|is never|may be|may not be|may commonly be|never is) an appropriate definition of (\w+)(?: in certain contexts| in any context)?$',s)
    if m: 
        pre=s.startswith('In no context'); 
        return m.group(3),m.group(1),('not' in m.group(2) or 'never' in m.group(2) or pre)
    return None
